#include "instaham/cutter/TerminalGeometry.hpp"
#include "instaham/MaskUtils.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
#include <map>
#include <numeric>
#include <stdexcept>
#include <tuple>
namespace instaham { namespace {
struct Node{PointRadius row;cv::Point2d c;};
struct Edge{int v;double d;};
struct SideInfo{std::string side;std::vector<int> leaves;std::vector<std::vector<int>> paths;std::vector<int> common;int basis=-1;};
struct Eval{bool valid=false,pq=false;int node=-1,pos=-1;double radius=0,error=1e300,cap=1e300;};
struct UF{std::vector<int>p;UF(int n):p(n){std::iota(p.begin(),p.end(),0);}int f(int x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}void u(int a,int b){a=f(a);b=f(b);if(a!=b)p[b]=a;}};
std::vector<Node> cluster(const std::vector<PointRadius>&r,double eps){int n=r.size();UF uf(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(cv::norm(r[i].center-r[j].center)<=eps)uf.u(i,j);std::vector<int>roots;std::vector<std::vector<int>>groups;for(int i=0;i<n;i++){int rt=uf.f(i);auto it=std::find(roots.begin(),roots.end(),rt);if(it==roots.end()){roots.push_back(rt);groups.push_back({i});}else groups[it-roots.begin()].push_back(i);}std::vector<Node>o;for(auto&g:groups){int win=g[0];for(int i:g){auto key=[&](int k){return std::tuple<double,double,int>(r[k].radius,-std::abs(r[k].radiusMinusEdt),-r[k].pIndex);};if(key(i)>key(win))win=i;}o.push_back({r[win],r[win].center});}return o;}
std::vector<std::vector<Edge>> mst(const std::vector<Node>&n){int N=n.size();std::vector<std::vector<Edge>>a(N);if(N<2)return a;std::vector<char>in(N,0);std::vector<double>best(N,1e300);std::vector<int>par(N,-1);best[0]=0;for(int k=0;k<N;k++){int u=-1;double bd=1e300;for(int i=0;i<N;i++)if(!in[i]&&best[i]<bd){bd=best[i];u=i;}if(u<0)break;in[u]=1;if(par[u]>=0){double d=cv::norm(n[u].c-n[par[u]].c);a[u].push_back({par[u],d});a[par[u]].push_back({u,d});}for(int v=0;v<N;v++)if(!in[v]){double d=cv::norm(n[u].c-n[v].c);if(d<best[v]){best[v]=d;par[v]=u;}}}return a;}
void rootTree(const std::vector<std::vector<Edge>>&a,int root,std::vector<int>&parent){parent.assign(a.size(),-1);parent[root]=root;std::vector<int>st{root};while(!st.empty()){int u=st.back();st.pop_back();for(auto e:a[u])if(parent[e.v]<0){parent[e.v]=u;st.push_back(e.v);}}}
std::vector<int> pathRoot(const std::vector<int>&p,int root,int node){std::vector<int>x{node};for(int guard=0;x.back()!=root&&guard<(int)p.size()+2;guard++){int q=p[x.back()];if(q<0)throw std::runtime_error("Disconnected medial tree");x.push_back(q);}std::reverse(x.begin(),x.end());return x;}
std::vector<int> commonPrefix(const std::vector<std::vector<int>>&p){if(p.empty())return{};size_t lim=p[0].size();for(auto&x:p)lim=std::min(lim,x.size());std::vector<int>c;for(size_t i=0;i<lim;i++){bool ok=true;for(size_t j=1;j<p.size();j++)if(p[j][i]!=p[0][i]){ok=false;break;}if(!ok)break;c.push_back(p[0][i]);}return c;}
SideInfo sideInfo(const std::vector<Node>&nodes,const std::vector<std::vector<Edge>>&adj,const std::vector<int>&parent,int anchor,const SelleResult&s,const std::string&side,double frac){SideInfo r;r.side=side;std::vector<double>pr(nodes.size());for(size_t i=0;i<nodes.size();i++){cv::Vec2d d(nodes[i].c.x-s.frameOrigin.x,nodes[i].c.y-s.frameOrigin.y);pr[i]=dot2(d,s.major);}double ap=pr[anchor],ext=side=="low"?*std::min_element(pr.begin(),pr.end()):*std::max_element(pr.begin(),pr.end());double th=side=="low"?ap-frac*(ap-ext):ap+frac*(ext-ap);std::vector<int>leaves;for(int i=0;i<(int)adj.size();i++)if(i!=anchor&&adj[i].size()==1)leaves.push_back(i);for(int i:leaves)if((side=="low"&&pr[i]<=th)||(side=="high"&&pr[i]>=th))r.leaves.push_back(i);if(r.leaves.empty()){std::vector<int>cand;for(int i:leaves)if((side=="low"&&pr[i]<ap)||(side=="high"&&pr[i]>ap))cand.push_back(i);if(!cand.empty()){auto cmp=[&](int a,int b){return pr[a]<pr[b];};r.leaves.push_back(side=="low"?*std::min_element(cand.begin(),cand.end(),cmp):*std::max_element(cand.begin(),cand.end(),cmp));}}if(r.leaves.empty()){int ix=side=="low"?std::min_element(pr.begin(),pr.end())-pr.begin():std::max_element(pr.begin(),pr.end())-pr.begin();r.leaves={ix};}for(int l:r.leaves)r.paths.push_back(pathRoot(parent,anchor,l));r.common=commonPrefix(r.paths);if(r.common.empty())r.common={anchor};r.basis=r.common.back();return r;}
bool inside(const cv::Mat&m,const cv::Point2d&p){return maskContainsNearest(m,p);}
bool rayExit(const cv::Mat&m,const cv::Point2d&o,const cv::Vec2d&dir,double step,int bisect,double&dist){if(!inside(m,o))return false;auto d=unitVec(dir);double maxD=hypot(m.rows,m.cols)+5,prev=0;for(double t=std::max(.20,step);t<=maxD;t+=std::max(.20,step)){cv::Point2d p(o.x+t*d[0],o.y+t*d[1]);if(!inside(m,p)){double lo=prev,hi=t;for(int i=0;i<bisect;i++){double md=.5*(lo+hi);cv::Point2d q(o.x+md*d[0],o.y+md*d[1]);if(inside(m,q))lo=md;else hi=md;}dist=.5*(lo+hi);return true;}prev=t;}return false;}
cv::Vec2d outward(const std::vector<int>&path,const std::vector<Node>&nodes,int pos,const SelleResult&s,const std::string&side,int back){int st=std::max(0,pos-back);cv::Vec2d t;if(pos>st)t={nodes[path[pos]].c.x-nodes[path[st]].c.x,nodes[path[pos]].c.y-nodes[path[st]].c.y};else t=s.major;if(side=="low"&&pos==st)t=-t;if(hypot(t[0],t[1])<=1e-9){t=s.major;if(side=="low")t=-t;}return unitVec(t);}
Eval evalNode(const cv::Mat&m,const Node&n,const cv::Vec2d&o,const TerminalConfig&cfg){Eval e;e.radius=std::max(n.row.radius,1e-6);auto out=unitVec(o);cv::Vec2d normal(-out[1],out[0]);double L,R,F;bool ok=rayExit(m,n.c,normal,cfg.rayStepPx,cfg.rayBisectionSteps,L)&&rayExit(m,n.c,-normal,cfg.rayStepPx,cfg.rayBisectionSteps,R)&&rayExit(m,n.c,out,cfg.rayStepPx,cfg.rayBisectionSteps,F);cv::Vec2d pc(n.row.p.x-n.c.x,n.row.p.y-n.c.y),qc(n.row.q.x-n.c.x,n.row.q.y-n.c.y);e.pq=dot2(pc,normal)*dot2(qc,normal)<0;if(!ok)return e;e.valid=true;double lm=abs(L-e.radius)/e.radius,rm=abs(R-e.radius)/e.radius;e.cap=abs(F-e.radius)/e.radius;e.error=std::max({lm,rm,e.cap});return e;}
int selectNode(const SideInfo&si,const std::vector<Node>&nodes,const SelleResult&s,const cv::Mat&m,const TerminalConfig&cfg){int start=std::max(0,(int)si.common.size()-std::max(1,cfg.lookbackNodes));std::vector<Eval>all;for(int pos=start;pos<(int)si.common.size();pos++){int node=si.common[pos];Eval e=evalNode(m,nodes[node],outward(si.common,nodes,pos,s,si.side,cfg.tangentBackNodes),cfg);e.node=node;e.pos=pos;all.push_back(e);}std::vector<Eval*>valid,cap;for(auto&e:all)if(e.valid){valid.push_back(&e);if(e.cap<=cfg.capMismatchMax)cap.push_back(&e);}auto pool=!cap.empty()?cap:valid;if(pool.empty())return si.basis;double be=1e300;for(auto*e:pool)be=std::min(be,e->error);std::vector<Eval*>near;for(auto*e:pool)if(e->error<=be+cfg.nearTieScore)near.push_back(e);std::vector<Eval*>bil;for(auto*e:near)if(e->pq)bil.push_back(e);auto&fin=!bil.empty()?bil:near;Eval*best=fin[0];for(auto*e:fin)if(std::tuple<double,int>(e->radius,e->pos)>std::tuple<double,int>(best->radius,best->pos))best=e;return best->node;}
}
TerminalResult buildTerminalTrunk(const SelleResult&s,const cv::Mat&ji,const TerminalConfig&cfg){TerminalResult out;try{auto nodes=cluster(s.retained,cfg.clusterEpsPx);if(nodes.size()<3)throw std::runtime_error("Too few clustered medial nodes");auto adj=mst(nodes);int anchor=0;double bd=1e300;for(int i=0;i<(int)nodes.size();i++){double d=cv::norm(nodes[i].c-s.frameOrigin);if(d<bd){bd=d;anchor=i;}}std::vector<int>parent;rootTree(adj,anchor,parent);auto low=sideInfo(nodes,adj,parent,anchor,s,"low",cfg.leafFraction),high=sideInfo(nodes,adj,parent,anchor,s,"high",cfg.leafFraction);int ln=selectNode(low,nodes,s,ji,cfg),hn=selectNode(high,nodes,s,ji,cfg);auto trimPath=[&](const SideInfo&si,int selected){auto p=si.common;auto it=std::find(p.begin(),p.end(),selected);if(it==p.end())throw std::runtime_error("Selected terminal not on common trunk");p.erase(it+1,p.end());return p;};auto lp=trimPath(low,ln),hp=trimPath(high,hn);if(lp.front()!=hp.front())throw std::runtime_error("Terminal paths have different anchors");std::vector<int>seq(lp.rbegin(),lp.rend());seq.insert(seq.end(),hp.begin()+1,hp.end());if(seq.size()<3)throw std::runtime_error("Selected trunk too short");double lr=nodes[ln].row.radius,hr=nodes[hn].row.radius;if(std::abs(lr-hr)<=1e-9)throw std::runtime_error("Selected terminal radii tied");bool headLow=lr<hr;if(!headLow)std::reverse(seq.begin(),seq.end());out.trunk.headEnd=headLow?"low":"high";out.trunk.rumpEnd=headLow?"high":"low";out.trunk.headRadius=std::min(lr,hr);out.trunk.rumpRadius=std::max(lr,hr);for(int n:seq){out.trunk.nodes.push_back(n);out.trunk.centers.push_back(nodes[n].c);out.trunk.radii.push_back(nodes[n].row.radius);}out.valid=true;}catch(const std::exception&e){out.error=e.what();}return out;}
}
